import re,glob
exports={}
for f in glob.glob('js/*.js'):
    src=open(f).read()
    names=set()
    for m in re.finditer(r'export\s+(?:async\s+)?(?:function|const|let|class)\s+(\w+)',src): names.add(m.group(1))
    for m in re.finditer(r'export\s*\{([^}]*)\}',src):
        for x in m.group(1).split(','):
            x=x.strip().split(' as ')[-1].strip()
            if x: names.add(x)
    exports[f]=names
# collect imports
for f in glob.glob('js/*.js'):
    src=open(f).read()
    for m in re.finditer(r"import\s*\{([^}]*)\}\s*from\s*'\./([\w-]+\.js)'",src,re.S):
        mod='js/'+m.group(2)
        for x in m.group(1).split(','):
            name=x.strip().split(' as ')[0].strip()
            if name and name not in exports.get(mod,set()):
                print('MISSING',f,'imports',name,'from',mod)
print('done')
